#include <iostream>
#include <vector>
using namespace std;

long long count_windows(const vector<long long>& a, long long target) {
    int l = 0;
    long long sum = 0;
    long long answer = 0;

for (int r = 0; r < static_cast<int>(a.size()); ++r) {
    sum += a[r];
    while (l <= r && sum > target) {
        sum -= a[l];
        ++l;
    }

        if (sum == target) {
            ++answer;
        }
    }
    return answer;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int size;
    long long target;
    cin >> size >> target;
    vector<long long> a(size);
    for (long long& value : a) {
        cin >> value;
    }
    cout << count_windows(a, target) << '\n';
    return 0;
}

